    {
      "name": "Stats Bar",
      "role": "Performance metric display (e.g., '% of real-world sites with good Core Web Vitals')",
      "description": "Horizontal bar chart on a #060913 background with 1px #1f232 border, 8px radius. Bars in the brand gradient (#3245ff → #b845ed). Label in 14px monospace, value in 16px weight 600 #f2f6fa."
